S.append(TB(c,B+' · 1','Các nhóm nghề chính',['Nhóm nghề','Việc làm','Ví dụ vị trí'],[['<b>Phát triển phần mềm</b>','thiết kế, lập trình, kiểm thử','lập trình viên, kiểm thử viên'],['<b>Hạ tầng, mạng</b>','xây dựng, quản trị hệ thống mạng','quản trị mạng, kĩ sư hệ thống'],['<b>Dữ liệu, AI</b>','thu thập, phân tích, xây mô hình','chuyên gia dữ liệu, kĩ sư AI'],['<b>An toàn thông tin</b>','bảo vệ hệ thống, dữ liệu','chuyên viên bảo mật'],['<b>Dịch vụ CNTT</b>','hỗ trợ, sửa chữa, bảo trì','kĩ thuật viên, hỗ trợ người dùng'],['<b>Thiết kế, sáng tạo số</b>','giao diện, đồ hoạ, game','UI/UX, thiết kế đồ hoạ']],note=KEY('Một người có thể chuyển giữa các nhóm nghề nhờ nền tảng <b>chung</b>: tư duy máy tính, lập trình, mạng.')))
S.append(S2(c,B+' · 2','Dịch vụ sửa chữa và bảo trì máy tính',card('Khái niệm',ul(['Nghề <b>duy trì sự ổn định</b> của máy tính và thiết bị liên quan; <b>hỗ trợ kĩ thuật</b> khi cần.','<b>Sửa chữa</b>: khắc phục khi hỏng. <b>Bảo trì</b>: làm định kì để <b>phòng ngừa</b> hỏng.'],6)),KEY('Nhiều tổ chức <b>trả phí bảo trì định kì</b> vì sự cố làm <b>gián đoạn công việc, mất dữ liệu</b> → thiệt hại lớn hơn chi phí bảo trì.')))
S.append(TB(c,B+' · 2','Công việc chính của nghề',['Nhóm','Công việc cụ thể'],[['<b>Phần cứng</b>','kiểm tra, duy trì hoạt động; tìm và khắc phục lỗi; lắp, thay linh kiện; nâng cấp RAM, ổ cứng, mainboard'],['<b>Phần mềm</b>','cài, cập nhật hệ điều hành, driver, ứng dụng văn phòng; cấu hình mạng; quét mã độc, cài phần mềm diệt virus'],['<b>Hỗ trợ người dùng</b>','hướng dẫn sử dụng đúng cách, giải đáp, tư vấn mua sắm thiết bị'],['<b>Quản lí</b>','lập danh sách thiết bị, lịch bảo trì, ghi chép sự cố']],note=KEY('Bảo trì định kì: <b>vệ sinh</b>, <b>cập nhật</b>, <b>sao lưu</b>, <b>kiểm tra ổ cứng, nhiệt độ</b>, quét mã độc.')))
