S.append(TB(c,B+' · 2','Triệu chứng thường gặp và nguyên nhân',['Triệu chứng','Nguyên nhân có thể','Cách xử lí'],[['Máy chạy chậm','đầy ổ đĩa, nhiều chương trình nền, mã độc','dọn dẹp, quét virus, nâng RAM/SSD'],['Không lên nguồn','hỏng nguồn, RAM lỏng, dây cắm','kiểm tra dây, nguồn, cắm lại RAM'],['Tự khởi động lại','quá nhiệt, nguồn yếu','vệ sinh quạt, tra keo tản nhiệt'],['Không vào mạng','sai cấu hình, hỏng card mạng/dây','kiểm tra IP, DNS, dây, router'],['Màn hình xanh','lỗi driver, RAM, ổ cứng','cập nhật driver, kiểm tra RAM, ổ đĩa']],note=WARN('Ngắt nguồn điện, dùng vòng chống tĩnh điện khi mở máy; không chạm linh kiện bằng tay ướt.')))
