S.append(TB(c,B+' · 4','So sánh một số nghề CNTT',['Nghề','Công việc cốt lõi','Kĩ năng nổi bật'],[['Lập trình viên','viết, kiểm thử chương trình','tư duy thuật toán, ngôn ngữ lập trình'],['Quản trị mạng','vận hành, giám sát mạng','giao thức, cấu hình thiết bị'],['Chuyên gia dữ liệu','phân tích, dự đoán','thống kê, Python, SQL'],['An toàn thông tin','phát hiện, ngăn chặn tấn công','mật mã, hệ thống, mạng'],['Kĩ thuật viên bảo trì','sửa chữa, hỗ trợ','phần cứng, giao tiếp']],note=KEY('Chọn nghề dựa trên <b>sở thích, năng lực, giá trị</b> và <b>nhu cầu xã hội</b>.')))
S.append(S2(c,B+' · 4','Tìm hiểu thông tin hướng nghiệp',card('Nguồn tin cậy',ul(['Website của <b>trường đại học, cao đẳng</b>, Bộ Giáo dục.','<b>Cổng thông tin việc làm</b>, báo cáo thị trường lao động.','Trải nghiệm thực tế: <b>tham quan</b>, trò chuyện với người làm nghề.','Khoá học, câu lạc bộ tin học.'],6)),KEY('Kiểm tra <b>nguồn, ngày đăng</b>, so sánh nhiều nguồn; cẩn thận quảng cáo “<b>học nhanh – lương cao</b>”.')+WARN('Đừng chọn nghề chỉ vì <b>mức lương</b> hay lời bạn bè; hãy thử và đánh giá bản thân.')))
